```css
.track{position:relative;width:100%;height:120px}
.runner{
  position:absolute;top:0;left:0;
  width:16px;height:16px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,#fff,#6c8cff);
  box-shadow:0 0 16px #6c8cff;
  offset-path: path("M 10 90 C 60 10, 120 10, 160 60 S 240 110, 300 30");
