```js
loadBtn.addEventListener('click', () => {
  if(loadBtn.classList.contains('loading')||loadBtn.classList.contains('done')) return;
  loadBtn.classList.add('loading');
  loadBtn.querySelector('.lbl').textContent='提交中';
  setTimeout(()=>{
    loadBtn.classList.remove('loading');
    loadBtn.classList.add('done');
    loadBtn.querySelector('.lbl').textContent='已完成 ✓';
    setTimeout(()=>{loadBtn.classList.remove('done');loadBtn.querySelector('.lbl').textContent='提交';},1500);
  },1600);
});
```

**打字机** 用 JS 循环实现。

```js
const typeEl = document.getElementById('typeText');
const words = ['Hello, 动画！','纯 CSS + JS','无任何依赖'];
let wi=0, ci=0, deleting=false;
function tick(){
  const w = words[wi];
  if(!deleting){
    ci++;
    typeEl.textContent = w.slice(0,ci);
    if(ci===w.length){ deleting=true; return setTimeout(tick, 1200); }
    setTimeout(tick, 110);
  } else {
    ci--;
    typeEl.textContent = w.slice(0,ci);
    if(ci===0){ deleting=false; wi=(wi+1)%words.length; return setTimeout(tick, 300); }
    setTimeout(tick, 55);
  }
}
tick();
```

