```js
/* 2. 打字机 */
(function(){
  const el = document.getElementById('typeText');
  const words = ['Hello, 动画！', '纯 CSS + JS 实现', '无任何外部依赖'];
  let wi = 0, ci = 0, del = false;
  function tick(){
    const w = words[wi];
    ci += del ? -1 : 1;
    el.textContent = w.slice(0, ci);
    let delay = del ? 55 : 120;
    if(!del && ci === w.length){ del = true; delay = 1300; }
    else if(del && ci === 0){ del = false; wi = (wi + 1) % words.length; delay = 320; }
    setTimeout(tick, delay);
  }
  tick();
})();
```
注意：`del` 在 0 处翻转之后延迟才变成 320 毫秒。OK。

边缘情况：一开始 ci=0，del=false → ci=1 → 没问题。

