/* 3. 进度条 */
(function(){
  const fill = document.getElementById('progFill');
  let p = 0;
  setInterval(()=>{
    p += 0.012;
    const v = 50 + 50 * Math.sin(p * Math.PI * 2 - Math.PI/2);
    fill.style.width = v.toFixed(1) + '%';
  }, 40);
})();
