    if(btn.classList.contains('loading') || btn.classList.contains('done')) return;
    btn.classList.add('loading');
    lbl.textContent = '提交中';
    setTimeout(()=>{
      btn.classList.remove('loading');
      btn.classList.add('done');
      lbl.textContent = '已完成 ✓';
      setTimeout(()=>{
